const SIZE = 1000, OVERLAP = 150, MIN = 20, SEPS = ['\n\n', '\n', '. ', '؟ ', '! ', ' '];
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.noSplit) { out.push({ json: { ...j, chunkIndex: 0 } }); continue; }
  const t = (j.pageContent ?? '').trim();
  let s = 0, n = 0;
  while (s < t.length) {
    let e = Math.min(s + SIZE, t.length);
    if (e < t.length) { // اقطع على حدود فقرة/جملة/كلمة
      const off = s + Math.floor(SIZE * 0.6);
      const win = t.slice(off, e);
      for (const sep of SEPS) {
        const k = win.lastIndexOf(sep);
        if (k >= 0) { e = off + k + sep.length; break; }
      }
    }
    const c = t.slice(s, e).trim();
    if (c.length >= MIN) {
      out.push({ json: {
        fileName: j.fileName ?? '', kind: j.kind ?? '', ext: j.ext ?? '',
        driveFileId: j.driveFileId ?? '', driveFileName: j.driveFileName ?? '',
        pageContent: c, chunkIndex: n++,
      } });
    }
    if (e >= t.length) break;
    s = Math.max(e - OVERLAP, s + 1);
  }
}
return out;

