const MAX_ENTRIES = 1000;
const ALLOW_ZIP = $runIndex === 0; // zip داخل zip = skip (حماية)
const EXT = {
  text: ['txt','md','markdown','csv','tsv','json','jsonl','ndjson','log','yaml','yml','xml','html','htm','srt','vtt','ini','conf','sql'],
  ocr_image: ['png','jpg','jpeg','webp','heic','heif','bmp','tif','tiff','gif'],
  pdf: ['pdf'],
  office: ['docx','pptx','xlsx'],
  zip: ['zip'],
};
const kindByMime = (m) => {
  if (m.startsWith('application/pdf')) return 'pdf';
  if (m.startsWith('image/')) return 'ocr_image';
  if (m.startsWith('text/') || /json|xml/.test(m)) return 'text';
  if (/zip/.test(m)) return 'zip';
  return null;
};
const resolveSrc = (item, idx) => {
  const j = item.json ?? {};
  if (j.driveFileId) return { id: j.driveFileId, name: j.driveFileName };
  if (j.id) return { id: j.id, name: j.name };
  try { const s = $('Drive Trigger').itemMatching(idx).json; return { id: s.id, name: s.name }; }
  catch (e) { return { id: null, name: null }; }
};
const out = [];
for (const [idx, item] of $input.all().entries()) {
  const src = resolveSrc(item, idx);
  for (const bin of Object.values(item.binary ?? {})) {
    if (out.length >= MAX_ENTRIES) break;
    const name = bin.fileName ?? '';
    const base = name.split('/').pop();
    if (!base || base.startsWith('.') || name.includes('__MACOSX')) continue;
    const ext = (bin.fileExtension || (base.includes('.') ? base.split('.').pop() : '') || '').toLowerCase();
    let kind = Object.keys(EXT).find((k) => EXT[k].includes(ext)) ?? kindByMime((bin.mimeType ?? '').toLowerCase()) ?? 'unknown';
    if (kind === 'zip' && !ALLOW_ZIP) kind = 'skip';
    out.push({
      json: { fileName: name, ext, kind, driveFileId: src.id, driveFileName: src.name },
      binary: { data: bin },
      pairedItem: { item: idx },
    });
  }
}
return out;

const stripMarkup = (s) => s
  .replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<br\s*\/?>|<\/(p|div|h[1-6]|li|tr)>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');

const out = [];
for (const [i, item] of $input.all().entries()) {
  const key = Object.keys(item.binary ?? {})[0];
  if (!key) continue;
  const buf = await this.helpers.getBinaryDataBuffer(i, key);
  if (buf.subarray(0, 8192).includes(0)) continue;
  let text = buf.toString('utf8').replace(/^\uFEFF/, '');
  const bad = (text.match(/\uFFFD/g) ?? []).length;
  if (text.length && bad / text.length > 0.02) continue;
  const { fileName, ext, kind, driveFileId, driveFileName } = item.json;
  const push = (pageContent) => out.push({
    json: { fileName, ext, kind, driveFileId, driveFileName, pageContent },
    pairedItem: { item: i },
  });

  // CSV: كل سطر = chunk مع الهيدر
  if (ext === 'csv') {
    const [header, ...rows] = text.split(/\r?\n/).filter((l) => l.trim());
    for (const r of rows) push(header + '\n' + r);
    continue;
  }

   // JSON: array أو wrapper فيه cars[] — كل عربية = chunk واحد كامل
  if (ext === 'json') {
    try {
      const parsed = JSON.parse(text);
      const list = Array.isArray(parsed) ? parsed : (Array.isArray(parsed && parsed.cars) ? parsed.cars : null);
      if (list) {
        for (const o of list) {
          if (o && o.description_ar) {
            const id = String(o.id ?? '').padStart(3, '0');
            out.push({
              json: {
                fileName, ext, kind, driveFileId, driveFileName,
                pageContent: '[' + id + '] ' + (o.brand_ar ?? '') + ' ' + (o.brand_en ?? '') + ' ' + (o.model ?? '') + ' ' + (o.year ?? '') + '\n' + o.description_ar,
                noSplit: true, carId: id, brand: o.brand_en ?? '', model: o.model ?? '',
              },
              pairedItem: { item: i },
            });
          } else {
            push(JSON.stringify(o, null, 1));
          }
        }
        continue;
      }
    } catch (e) { /* مش JSON سليم، كمّل كنص عادي */ }
  }

  if (['html', 'htm', 'xml'].includes(ext)) text = stripMarkup(text);
  text = text
    .replace(/\u0000/g, '')
    .replace(/[\u0001-\u0008\u000B\u000C\u000E-\u001F]/g, '')
    .replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  if (text.length < 20) continue;
  push(text);
}
return out;

