// docx/pptx/xlsx = zip. نغير الـ metadata عشان Compression node يفكه.
return $input.all().map((item, i) => {
  const b = item.binary.data;
  b.mimeType = 'application/zip';
  b.fileExtension = 'zip';
  b.fileName = (b.fileName ?? 'file').replace(/\.[^.]+$/, '') + '.zip';
  return { json: item.json, binary: { data: b }, pairedItem: { item: i } };
});

const dec = (s) => s.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&amp;/g, '&');
const toText = (xml, para) => dec(
  xml.replace(new RegExp('</' + para + '>', 'g'), '\n')
     .replace(/<w:tab\/>/g, '\t').replace(/<w:br\/>/g, '\n')
     .replace(/<[^>]+>/g, '')
);
const PICK = {
  docx: { re: /^(document|header\d*|footer\d*|footnotes)\.xml$/, para: 'w:p' },
  pptx: { re: /^(slide|notesSlide)\d+\.xml$/, para: 'a:p' },
  xlsx: { re: /^sharedStrings\.xml$/, para: 'si' },
};
const out = [];
for (const [i, item] of $input.all().entries()) {
  let meta = item.json;
  if (!meta.driveFileId) { try { meta = $('Prep OOXML').itemMatching(i).json; } catch (e) { continue; } }
  const rule = PICK[meta.ext];
  if (!rule) continue;
  const entries = Object.entries(item.binary ?? {})
    .map(([key, b]) => ({ key, base: (b.fileName ?? '').split('/').pop() }))
    .filter((e) => rule.re.test(e.base))
    .sort((a, b) => a.base.localeCompare(b.base, undefined, { numeric: true }));
  const parts = [];
  for (const e of entries) {
    const buf = await this.helpers.getBinaryDataBuffer(i, e.key);
    parts.push(toText(buf.toString('utf8'), rule.para));
  }
  const text = parts.join('\n').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  if (text.length < 20) continue;
  const { fileName, ext, kind, driveFileId, driveFileName } = meta;
  out.push({ json: { fileName, ext, kind, driveFileId, driveFileName, pageContent: text }, pairedItem: { item: i } });
}
return out;

return $input.all().map((it, i) => {
  const m = $('OCR Loop').itemMatching(i).json;
  const text = (
    it.json.content?.parts?.map((p) => p.text ?? '').join('\n') ||
    it.json.text ||
    ''
  ).trim();
  return {
    json: { fileName: m.fileName, ext: m.ext, kind: m.kind, driveFileId: m.driveFileId, driveFileName: m.driveFileName, pageContent: text },
    pairedItem: { item: i },
