// Contract out: { ok: boolean, kind: 'audio'|'image', text: string, error?: string }
let kind = 'image';
try { kind = ($('Base64 to Binary1').first().binary?.data?.mimeType || '').startsWith('audio') ? 'audio' : 'image'; } catch (e) { /* media never loaded */ }
const j = $input.first().json ?? {};
const text = String(
  j.content?.parts?.map((p) => p.text ?? '').join('\n') || j.text || ''
).replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
if (!text) return [{ json: { ok: false, kind, text: '', error: j.error?.message || j.error || 'empty_result' } }];
return [{ json: { ok: true, kind, text } }];

// Run Once for All Items. In: 1 item from AI Agent. Out: 1 text item + N image items.
const MAX_IMAGES = 6;
const MAX_TEXT = 3800; // WhatsApp hard limit ~4096
// bucket MUST match ingestion workflow upload bucket (car-images, hyphen)
const IMAGES_BASE = 'https://gefaqoughgefhngorvyx.supabase.co/storage/v1/object/public/car-images/';
const FALLBACK = 'حصلت مشكلة بسيطة عندنا، ممكن تبعت سؤالك تاني؟';

const agent = $input.first().json ?? {};
const number = $('Extract Message3').first().json.number;
const raw = typeof agent.output === 'string' ? agent.output : '';
const steps = Array.isArray(agent.intermediateSteps) ? agent.intermediateSteps : [];

// URL ends only where extension is followed by a boundary => keeps thumb/x.jpg/800px-x.jpg intact
const IMG = /(?:https?:\/\/|images_real\/)[^\s"'<>\\\]]+?\.(?:jpe?g|png|webp)(?:\?[^\s"'<>\\\]]*?)?(?=$|[\s"'<>)\]\\,;])/gi;
const findImages = (s) => [...String(s).matchAll(IMG)].map((m) => m[0]);
const unescapeJson = (s) => s.replace(/\\\//g, '/').replace(/\\u0026/g, '&');

// Images ONLY from search_car_images tool results (no LLM-invented links)
const found = [];
for (const s of steps) {
  if (!String(s?.action?.tool ?? '').startsWith('search_car_images')) continue;
  const obs = typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation ?? '');
  found.push(...findImages(unescapeJson(obs)));
}

const toUrl = (p) => (/^https?:\/\//i.test(p) ? p : IMAGES_BASE + p.replace(/^\/+/, ''));
const images = [...new Set(found.map(toUrl))].slice(0, MAX_IMAGES);

const mdImg = new RegExp('!?\\[[^\\]]*\\]\\(\\s*' + IMG.source + '\\s*\\)', 'gi');
const text = raw
  .replace(/<think>[\s\S]*?<\/think>/gi, '')
  .replace(mdImg, '')
  .replace(IMG, '')
  .replace(/\(\s*\)/g, '')
  .replace(/^#{1,6}\s*(.+)$/gm, '*$1*')   // headers -> WhatsApp bold
  .replace(/\*\*(.+?)\*\*/g, '*$1*')       // **bold** -> *bold*
  .replace(/[ \t]+\n/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim()
  .slice(0, MAX_TEXT);

const extOf = (u) => (u.split('?')[0].match(/\.(png|webp|jpe?g)$/i)?.[1] ?? 'jpg').toLowerCase();
const mimeOf = (e) => (e === 'png' ? 'image/png' : e === 'webp' ? 'image/webp' : 'image/jpeg');

const out = [{ json: { endpoint: 'sendText', payload: { number, text: text || FALLBACK } } }];
images.forEach((media, i) => {
  const e = extOf(media);
  out.push({ json: { endpoint: 'sendMedia', payload: { number, mediatype: 'image', mimetype: mimeOf(e), fileName: `car_${i + 1}.${e}`, media, caption: '' } } });
});
return out;
